      genesisP2: { value: "ہم کتابِ پیدائش کو الگ الگ اور غیرمتعلق حوالوں کے مجموعے کے طور پر نہیں بلکہ ایک منظم ترتیب کے ساتھ پڑھاتے ہیں۔ اس کے لیے تحریری اسباق تیار کیے جاتے ہیں، اور متعلقہ بائبلی شخصیات اور موضوعات کا بھی مطالعہ کرایا جاتا ہے۔", source: "author", published: true, reviewed: true, sourceHash: "9316309736f6dfc5" },
