      genesisP4: { value: "یہ مطالعہ کتابِ پیدائش کے تعارف سے شروع ہوتا ہے اور بائبلی متن کو ایک منظم ترتیب کے ساتھ آگے بڑھاتا ہے۔ جیسے جیسے کورس آگے بڑھتا ہے، طلبہ سے صرف مواد پڑھنے کی توقع نہیں کی جاتی بلکہ تحریری اسائنمنٹس کے ذریعے ان کی سمجھ اور مطالعے کا بھی جائزہ لیا جاتا ہے۔", source: "author", published: true, reviewed: true, sourceHash: "1fb355e97c40d1f5" },
      genesisP5: { value: "طلبہ اپنے اسائنمنٹس سیمنری کو واپس جمع کرواتے ہیں، اور ان کے کام اور تعلیمی پیش رفت کا ریکارڈ محفوظ رکھا جاتا ہے۔", source: "author", published: true, reviewed: true, sourceHash: "6dc1dfc1a7f449d0" },
      purposeHeading: { value: "ہماری تعلیمی غرض و غایت", source: "author", published: true, reviewed: true, sourceHash: "c81ab46ecde98154" },
      purposeP1: { value: "سیمنری کا مقصد صرف بائبل کے بارے میں معلومات فراہم کرنا نہیں ہے۔", source: "author", published: true, reviewed: true, sourceHash: "a2de43d5a84f98a3" },
      purposeP2: { value: "ہم طلبہ کی مدد کرنا چاہتے ہیں تاکہ وہ:", source: "author", published: true, reviewed: true, sourceHash: "902583660d994d15" },
      purposeItem1: { value: "کتابِ مقدس کو منظم انداز میں سمجھ سکیں۔", source: "author", published: true, reviewed: true, sourceHash: "d51a11ff13e8799b" },
      purposeItem2: { value: "بائبلی سچائی کی مضبوط بنیاد حاصل کر سکیں۔", source: "author", published: true, reviewed: true, sourceHash: "cb9cc645f2d6d833" },
      purposeItem3: { value: "بائبلی شخصیات اور واقعات کا اُن کے درست سیاق و سباق میں مطالعہ کر سکیں۔", source: "author", published: true, reviewed: true, sourceHash: "7c12f376f19e326c" },
      purposeItem4: { value: "بائبلی اور الٰہیاتی موضوعات پر سنجیدگی سے غور و فکر کر سکیں۔", source: "author", published: true, reviewed: true, sourceHash: "c1662b73218ba299" },
      purposeItem5: { value: "کتابِ مقدس کے آزادانہ مطالعے کی صلاحیت پیدا کر سکیں۔", source: "author", published: true, reviewed: true, sourceHash: "e571fab785c05dff" },
      purposeItem6: { value: "بائبلی علم کو اپنی مسیحی زندگی اور خدمت میں ذمہ داری کے ساتھ استعمال کر سکیں۔", source: "author", published: true, reviewed: true, sourceHash: "d54215dd59956507" },
      purposeItem7: { value: "کلیسیا اور مسیحی خدمت کے لیے خود کو وفاداری کے ساتھ تیار کر سکیں۔", source: "author", published: true, reviewed: true, sourceHash: "c92144cf778d3e88" },
      purposeP3: { value: "اس طریقۂ کار کے ذریعے ہم مسیحیوں کو گہرے بائبلی فہم کے لیے تیار کرنا چاہتے ہیں، جبکہ اُن غیرمسیحی افراد کے لیے بھی کتابِ مقدس کی تعلیم اور اُس کے پیغام تک رسائی آسان بنانا چاہتے ہیں جو اس کا مطالعہ کرنے میں دلچسپی رکھتے ہیں۔", source: "author", published: true, reviewed: true, sourceHash: "2270b28666a6fdd3" },
      reachHeading: { value: "ایسی سیمنری جو آپ کی دسترس میں ہو", source: "author", published: true, reviewed: true, sourceHash: "3950ee20d96634bb" },
      reachP1: { value: "بیت لحم تھیالوجیکل سیمنری بائبلی تعلیم کی راہ میں غیرضروری رکاوٹیں کم کرنے کے ہمارے عزم کی نمائندگی کرتی ہے۔", source: "author", published: true, reviewed: true, sourceHash: "0f63f8dfaa887302" },
      reachP2: { value: "ہم سمجھتے ہیں کہ کسی طالب علم کو صرف بائبل کا مطالعہ شروع کرنے کے لیے اپنا شہر چھوڑنے، کسی دوسرے صوبے کا سفر کرنے یا کسی فزیکل ادارے میں داخل ہونے کی ضرورت نہیں ہونی چاہیے۔", source: "author", published: true, reviewed: true, sourceHash: "117745b18548a757" },
      reachP3: { value: "واٹس ایپ کے ذریعے سیمنری طالب علم تک اُس کی اپنی جگہ پر پہنچ سکتی ہے۔", source: "author", published: true, reviewed: true, sourceHash: "dd894241c103fcb2" },
      reachP4: { value: "ہمارا وژن یہ ہے کہ ہر اُس شخص کے لیے بائبلی تعلیم قابلِ رسائی ہو جو خدا کے کلام کا مطالعہ کرنا چاہتا ہے—خواہ وہ کسی بڑے شہر میں رہتا ہو، کسی چھوٹے قصبے میں یا کسی دور دراز علاقے میں۔", source: "author", published: true, reviewed: true, sourceHash: "66f3060f0eea642e" },
      reachP5: { value: "خدا کی طرف سے ضروری وسائل فراہم ہونے پر ہم اس کام کو مزید ترقی دینے اور ڈیجیٹل پلیٹ فارمز کے ساتھ ساتھ ایک مخصوص موبائل ایپلی کیشن کے ذریعے وسعت دینے کی امید رکھتے ہیں، تاکہ پورے پاکستان میں منظم بائبلی اور الٰہیاتی تعلیم تک رسائی مزید وسیع ہو سکے۔", source: "author", published: true, reviewed: true, sourceHash: "46ca7583dad9a3d5" },
      reachP6: { value: "بائبلی تعلیم جغرافیائی حدود تک محدود نہیں ہونی چاہیے۔ ہماری خواہش ہے کہ سیمنری کو طالب علم کے قریب لایا جائے۔", source: "author", published: true, reviewed: true, sourceHash: "08881219a101ebba" },
